<?php
namespace App\Services;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Http;
class ChachaAiService {
 public function answer(int $userId,string $message):array{$context=['products'=>DB::table('products')->select('id','title','sku','retail_price','wholesale_price','group_price','stock_qty')->where('status','active')->limit(30)->get()->toArray(),'orders'=>DB::table('orders')->select('id','order_number','status')->where('user_id',$userId)->latest('id')->limit(10)->get()->toArray()];$key=config('services.gemini.api_key');if(!$key)return ['message'=>'Chacha is temporarily unavailable. Please contact a human agent.','handoff'=>true];$response=Http::timeout(30)->post('https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key='.$key,['system_instruction'=>['parts'=>[['text'=>'You are Chacha Prime shopping assistant. Never invent product, stock, price, order or policy facts. Escalate unresolved payment, fraud, security and account issues to human support.']]],'contents'=>[['role'=>'user','parts'=>[['text'=>"Context:\n".json_encode($context)."\nCustomer:\n".$message]]]],'generationConfig'=>['temperature'=>0.2]]);if(!$response->successful())return ['message'=>'I could not reach Chacha AI right now. Please contact support.','handoff'=>true];$text=data_get($response->json(),'candidates.0.content.parts.0.text','Please contact support.');return ['message'=>$text,'handoff'=>(bool)preg_match('/human agent|support|payment dispute|fraud|security/i',$text)];}
}